#[test]
fn actionable_board_preserves_decisions_and_tracks_pending_only() {
    let store = store();
    let proposed = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0030-proposed.md".into(),
                title: "Proposed".into(),
                summary: "review me".into(),
                status: DesignStatus::Proposed,
                proposed_by: Some("planner".into()),
            },
            NOW,
        )
        .unwrap();
    let pending = store
        .register_design_item(
            "design:0031-pending",
            "docs/adr/0031-pending.md",
            "Pending",
            "promote me",
            Some("planner"),
            NOW + 1,
        )
        .unwrap();
    assert!(store
        .decide_design_item(
            &pending.id,
            DesignStatus::Accepted,
            "reviewer",
            None,
            NOW + 2,
        )
        .unwrap());

    let before = store.get_design_item(&pending.id).unwrap().unwrap();
    let reconciled = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: pending.adr_path.clone(),
                title: "Repository status must not overwrite the decision".into(),
                summary: "changed".into(),
                status: DesignStatus::Rejected,
                proposed_by: None,
            },
            NOW + 3,
        )
        .unwrap();
    // Derived facts follow the ADR file; the decision and its promotion state
    // are durable and survive a repository pass that disagrees with them.
    assert_eq!(
        reconciled.title,
        "Repository status must not overwrite the decision"
    );
    assert_eq!(reconciled.summary, "changed");
    assert_eq!(reconciled.status, before.status);
    assert_eq!(reconciled.decided_by, before.decided_by);
    assert_eq!(reconciled.proposed_by, before.proposed_by);
    assert_eq!(reconciled.promotion_status, before.promotion_status);

    let rows = store.actionable_design_items().unwrap();
    assert_eq!(
        rows.iter().map(|item| item.id.as_str()).collect::<Vec<_>>(),
        vec![proposed.id.as_str(), pending.id.as_str(),]
    );

    let objective = goal(&store);
    store
        .materialize_design_item(
            &pending.id,
            &create_plan(&objective.id, "Implement pending"),
            "reviewer",
            false,
            NOW + 4,
        )
        .unwrap();
    assert_eq!(
        store
            .actionable_design_items()
            .unwrap()
            .iter()
            .map(|item| item.id.as_str())
            .collect::<Vec<_>>(),
        vec![proposed.id.as_str()]
    );
}

#[test]
fn deferring_parks_a_proposed_design_and_resume_returns_it_to_the_board() {
    let store = store();
    let item = store
        .register_design_item(
            "design:0077-crowded-board",
            "docs/adr/0077-crowded-board.md",
            "A crowded board is not a decision",
            "park stale proposals without rejecting them",
            Some("planner"),
            NOW,
        )
        .unwrap();

    let deferred = store
        .defer_design_item(&item.id, "monk-eee", "not this quarter", NOW + 1)
        .unwrap();

    assert_eq!(deferred.status, DesignStatus::Proposed);
    let record = deferred.deferred.expect("deferral recorded");
    assert_eq!(record.at, NOW + 1);
    assert_eq!(record.by, "monk-eee");
    assert_eq!(record.reason, "not this quarter");
    assert!(store.actionable_design_items().unwrap().is_empty());

    let resumed = store
        .resume_design_item(&item.id, "monk-eee", "back in scope", NOW + 2)
        .unwrap();
    assert!(resumed.deferred.is_none());
    assert_eq!(
        store
            .actionable_design_items()
            .unwrap()
            .into_iter()
            .map(|row| row.id)
            .collect::<Vec<_>>(),
        vec![item.id.clone()]
    );
    let actions = store.design_action_history(&item.id).unwrap();
    assert_eq!(
        actions
            .iter()
            .map(|action| action.action)
            .collect::<Vec<_>>(),
        vec![DesignActionKind::Defer, DesignActionKind::Resume]
    );
    assert_eq!(actions[1].human, "monk-eee");
    assert_eq!(actions[1].reason, "back in scope");
}

#[test]
fn design_promotion_is_read_only_and_resolves_materialized_provenance() {
    let store = store();
    let item = store
        .register_design_item(
            "design:0040-materialized",
            "docs/adr/0040-materialized.md",
            "Materialized",
            "ship it",
            Some("planner"),
            NOW,
        )
        .unwrap();
    assert!(store.design_promotion(&item.id).unwrap().is_none());
    assert!(store
        .decide_design_item(&item.id, DesignStatus::Accepted, "reviewer", None, NOW + 1,)
        .unwrap());
    assert!(store.design_promotion(&item.id).unwrap().is_none());

    let objective = goal(&store);
    let mut plan = create_plan(&objective.id, "Implement materialized");
    plan.constraints.push(DesignConstraintDraft {
        kind: GoalKind::Constraint,
        title: "Keep it deterministic".into(),
        statement: "no model on reconciliation".into(),
    });
    let created = store
        .materialize_design_item(&item.id, &plan, "reviewer", false, NOW + 2)
        .unwrap();
    let resolved = store.design_promotion(&item.id).unwrap().unwrap();

    assert_eq!(resolved.item, created.item);
    assert_eq!(resolved.goals[0].id, created.goals[0].id);
    assert_eq!(
        resolved
            .tasks
            .iter()
            .map(|task| &task.id)
            .collect::<Vec<_>>(),
        created
            .tasks
            .iter()
            .map(|task| &task.id)
            .collect::<Vec<_>>()
    );
    assert_eq!(
        resolved
            .constraints
            .iter()
            .map(|goal| &goal.id)
            .collect::<Vec<_>>(),
        created
            .constraints
            .iter()
            .map(|goal| &goal.id)
            .collect::<Vec<_>>()
    );
    assert_eq!(
        store.list_design_items(None, false, false).unwrap().len(),
        1
    );
}

/// The ghost-row scenario ADR-0042 exists for: renaming an ADR registers a new
/// design and orphans the old one, because reconciliation keys on the ADR path.
/// The orphan is unreachable — its path exists on no branch — but nothing could
/// remove it, so the Design Board kept offering rows that throw when opened.
#[test]
fn retiring_removes_an_orphaned_record_from_the_board_without_deleting_it() {
    let store = store();
    let orphan = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0036-one-work-surface.md".into(),
                title: "One Work surface".into(),
                summary: "renumbered away".into(),
                status: DesignStatus::Proposed,
                proposed_by: Some("workspace-sensor".into()),
            },
            NOW,
        )
        .unwrap();
    assert!(orphan.retired.is_none());
    assert_eq!(store.actionable_design_items().unwrap().len(), 1);

    let retired = store
        .retire_design_item(&orphan.id, "Lyndon Swan", "renumbered to ADR-0040", NOW + 1)
        .unwrap();

    // Attributed and reasoned, so the audit says who and why.
    let record = retired.retired.as_ref().expect("retirement recorded");
    assert_eq!(record.by, "Lyndon Swan");
    assert_eq!(record.reason, "renumbered to ADR-0040");
    assert_eq!(record.at, NOW + 1);

    // Off the working board, still in the durable audit view (ADR-0019).
    assert!(store.actionable_design_items().unwrap().is_empty());
    assert!(store
        .list_design_items(None, false, false)
        .unwrap()
        .is_empty());
    let audited = store.list_design_items(None, true, false).unwrap();
    assert_eq!(audited.len(), 1);
    assert_eq!(audited[0].id, orphan.id);
    assert_eq!(audited[0].adr_path, orphan.adr_path);
    assert_eq!(audited[0].status, orphan.status);
    assert!(store.get_design_item(&orphan.id).unwrap().is_some());
}

/// Retiring twice must not overwrite the first actor and reason: the guarded
/// update is what stops a second caller rewriting who retired the record.
#[test]
fn retiring_is_refused_twice_and_preserves_the_original_attribution() {
    let store = store();
    let item = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0037-one-work-surface.md".into(),
                title: "One Work surface".into(),
                summary: "renumbered away".into(),
                status: DesignStatus::Proposed,
                proposed_by: None,
            },
            NOW,
        )
        .unwrap();
    store
        .retire_design_item(&item.id, "first", "original reason", NOW + 1)
        .unwrap();

    let again = store.retire_design_item(&item.id, "second", "later reason", NOW + 2);
    assert!(again.is_err(), "a retired record must not be retired again");

    let record = store
        .get_design_item(&item.id)
        .unwrap()
        .unwrap()
        .retired
        .expect("still retired");
    assert_eq!(record.by, "first");
    assert_eq!(record.reason, "original reason");
}

