// ADR-0047. An imported status reflects a decision; it does not record one, so
// `decided_by` stays empty. Because deciding is guarded on `proposed`, such a
// row is frozen: it asserts a decision that can never be attributed to anyone.
// Observed live on ADR-0045, where a reviewer said "I agree with it" and there
// was no way to write that down.
#[test]
fn an_imported_status_can_be_reopened_but_a_real_decision_cannot() {
    let store = store();
    let item = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0045-fleet.md".into(),
                title: "A fleet is a distributed system".into(),
                summary: "treat agents as a distributed system".into(),
                status: DesignStatus::Accepted,
                proposed_by: None,
            },
            NOW,
        )
        .unwrap();

    // Imported at face value, and therefore unattributable and undecidable.
    assert_eq!(item.status, DesignStatus::Accepted);
    assert_eq!(item.decided_by, None);
    assert!(!store
        .decide_design_item(&item.id, DesignStatus::Accepted, "monk-eee", None, NOW)
        .unwrap());

    assert!(store.reopen_undecided_design(&item.id, NOW).unwrap());
    assert_eq!(
        store.get_design_item(&item.id).unwrap().unwrap().status,
        DesignStatus::Proposed
    );

    // Now decidable by a person — and that decision is not reopenable.
    assert!(store
        .decide_design_item(&item.id, DesignStatus::Accepted, "monk-eee", None, NOW)
        .unwrap());
    assert!(!store.reopen_undecided_design(&item.id, NOW).unwrap());
    let decided = store.get_design_item(&item.id).unwrap().unwrap();
    assert_eq!(decided.status, DesignStatus::Accepted);
    assert_eq!(decided.decided_by.as_deref(), Some("monk-eee"));
}

// Reopening is scoped to the damage it repairs: a design whose promotion has
// already materialised work rests on that acceptance, so it stays put.
#[test]
fn reopening_is_refused_once_promotion_has_left_not_required() {
    let store = store();
    let item = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0045-fleet.md".into(),
                title: "A fleet is a distributed system".into(),
                summary: "treat agents as a distributed system".into(),
                status: DesignStatus::Proposed,
                proposed_by: None,
            },
            NOW,
        )
        .unwrap();
    assert!(store
        .decide_design_item(&item.id, DesignStatus::Accepted, "monk-eee", None, NOW)
        .unwrap());
    // Strip the decider but keep promotion armed: the residual guard, not the
    // decided_by one, is what must refuse here.
    store
        .conn
        .execute(
            "UPDATE design_items SET decided_by = NULL WHERE id = ?1",
            rusqlite::params![item.id],
        )
        .unwrap();

    assert!(!store.reopen_undecided_design(&item.id, NOW).unwrap());
    assert_eq!(
        store.get_design_item(&item.id).unwrap().unwrap().status,
        DesignStatus::Accepted
    );
}

/// Register a design and have a person accept it, which is the only state from
/// which supersession is meaningful.
fn accepted_design(store: &crate::store::LodestarStore, path: &str, title: &str) -> String {
    let item = store
        .register_design_item(
            &crate::design::design_id_from_path(path),
            path,
            title,
            "summary",
            Some("agent"),
            NOW,
        )
        .unwrap();
    assert!(store
        .decide_design_item(&item.id, DesignStatus::Accepted, "monk-eee", None, NOW)
        .unwrap());
    item.id
}

// ADR-0050. The gap this closes: ADR-0018 says "Superseded by ADR-0032" and the
// ledger had no way to hold that, so the row sat `accepted` and every
// ledger-driven view showed a withdrawn decision as live.
#[test]
fn superseding_records_the_replacement_without_erasing_the_decision() {
    let store = store();
    let old = accepted_design(
        &store,
        "docs/adr/0018-single-checkout.md",
        "Single checkout",
    );
    let new = accepted_design(&store, "docs/adr/0032-fleet.md", "Fleet integration");

    let superseded = store
        .supersede_design_item(&old, &new, "monk-eee", NOW + 1)
        .unwrap();

    // The decision survives: it was accepted, and by whom, is still recorded.
    assert_eq!(superseded.status, DesignStatus::Accepted);
    assert_eq!(superseded.decided_by.as_deref(), Some("monk-eee"));
    let link = superseded.superseded.expect("supersession recorded");
    assert_eq!(link.by_design, new);
    assert_eq!(link.by, "monk-eee");
    assert_eq!(link.at, NOW + 1);
}

// A superseded design is no longer live work, so the board stops offering it —
// the same treatment retirement gets, for a different reason.
#[test]
fn a_superseded_design_leaves_the_actionable_board() {
    let store = store();
    let old = accepted_design(
        &store,
        "docs/adr/0018-single-checkout.md",
        "Single checkout",
    );
    let new = accepted_design(&store, "docs/adr/0032-fleet.md", "Fleet integration");
    assert_eq!(store.actionable_design_items().unwrap().len(), 2);

    store
        .supersede_design_item(&old, &new, "monk-eee", NOW + 1)
        .unwrap();

    let live: Vec<String> = store
        .actionable_design_items()
        .unwrap()
        .into_iter()
        .map(|item| item.id)
        .collect();
    assert_eq!(live, vec![new]);
    // Still in the durable audit view: superseding is not deleting (ADR-0019).
    assert_eq!(
        store.list_design_items(None, false, false).unwrap().len(),
        2
    );
}

// Superseding is a statement about a decision that was actually made. A row
// carrying an imported status with nobody behind it (the ADR-0047 shape) has no
// decision to supersede — it should be reopened and decided, or retired.
#[test]
fn a_status_nobody_decided_cannot_be_superseded() {
    let store = store();
    let undecided = store
        .reconcile_design_item(
            &DesignMetadata {
                adr_path: "docs/adr/0018-single-checkout.md".into(),
                title: "Single checkout".into(),
                summary: "imported".into(),
                status: DesignStatus::Accepted,
                proposed_by: None,
            },
            NOW,
        )
        .unwrap();
    let new = accepted_design(&store, "docs/adr/0032-fleet.md", "Fleet integration");
    assert_eq!(undecided.decided_by, None);

    let refused = store.supersede_design_item(&undecided.id, &new, "monk-eee", NOW + 1);
    assert!(refused.is_err());
    assert!(store
        .get_design_item(&undecided.id)
        .unwrap()
        .unwrap()
        .superseded
        .is_none());
}

